from collections import deque
out=[row[:] for row in g]
unresolved=[]
for r in range(30):
 for c in range(30):
  if g[r][c]!=6: continue
  q=deque([(r,c)]); seen={(r,c)}; donor=None
  while q:
   a,b=q.popleft()
   if g[a][b]!=6:
    donor=g[a][b]; break
   nxt=[(b,a)]
   if 2<=a<=29: nxt.append((31-a,b))
   for z in nxt:
    if 0<=z[0]<30 and 0<=z[1]<30 and z not in seen:
     seen.add(z); q.append(z)
  if donor is None: unresolved.append((r,c,seen))
  else: out[r][c]=donor
len(unresolved), [(r,c,out[r][c]) for r in range(30) for c in range(30) if g[r][c]==6]

